from collections import defaultdict


def signature(item):
    # Items with the same signature belong together.
    # Sorted characters group anagrams (words) or digit permutations (numbers).
    return "".join(sorted(str(item)))


def solve():
    words = ["listen", "silent", "enlist", "google", "inlets", "banana", "gogole"]
    groups = defaultdict(list)         # signature -> items that share it
    for word in words:
        groups[signature(word)].append(word)
    return max(groups.values(), key=len)


